        })
        bind(inputFrame, "BackgroundColor3", "Elevated")
        U.corner(inputFrame, 10)
        local inputStroke = U.stroke(inputFrame, Color3.new(1, 1, 1), 1, 0.85)
        bind(inputStroke, "Color", "Glass")
        local box = new("TextBox", {
