local function libraryLocaleOptions()
    local options, labels, map = {}, {}, {}
    for _, item in ipairs(LIBRARY_LOCALES) do
        local code, name = item[1], item[2]
        if not map[code] then
            local label = name .. " (" .. code .. ")"
            options[#options + 1] = label
            map[label] = code
            labels[code] = label
        end
    end
    table.sort(options)
    return options, labels, map
end

                                                                                                             
