local function normalizeImageAsset(imageReference)
    if type(imageReference) == "number" then
        if imageReference <= 0 then
            return nil
        end
        return "rbxassetid://" .. tostring(math.floor(imageReference))
    end
    if type(imageReference) ~= "string" then
        return nil
    end
    local value = imageReference:match("^%s*(.-)%s*$")
    if value == "" then
        return nil
    end
    local digits = value:match("^[%d]+$")
    if digits then
        return "rbxassetid://" .. digits
    end
    local assetId = value:match("[?&]id=(%d+)") or value:match("/asset/(%d+)")
    if assetId and (value:find("roblox.com", 1, true) or value:find("roblox", 1, true)) then
        return "rbxassetid://" .. assetId
    end
    return value
end

function Library:Translate(sourceText)
    return GGH.tr(sourceText)
end

local THEME_TOKEN_NAMES = {
    "Background", "Sidebar", "Surface", "Surface2", "Elevated", "Line",
    "Text", "Muted", "Faint", "Accent", "OnAccent", "Success", "Warning", "Danger", "Glass",
}

local function parseThemeColor(value)
    if typeof(value) == "Color3" then
        return value
    end
    if type(value) == "string" then
        local hex = value:gsub("^#", "")
        if hex:match("^%x%x%x%x%x%x$") then
            local success, result = pcall(Color3.fromHex, hex)
            if success then
                return result
            end
        end
    end
    return nil
end

function WindowClass:SetLanguage(languageCode)
    if type(languageCode) ~= "string" or not self.Languages or not self.Languages[languageCode] then
        return false
    end
    self.LanguageCode = languageCode
    self.State.set("language", languageCode)
    GGH.setLanguage(languageCode, self.Languages)
    if self.SetLibraryLanguage then self:SetLibraryLanguage(self.LibraryLanguageCode or "en") end
    if self.LanguageDropdown and self.LanguageDropdown.SetSilent then
        for label, code in pairs(self.LanguageCodeByLabel or {}) do
            if code == languageCode then
                self.LanguageDropdown:SetSilent(label)
                break
            end
        end
    end
    return true
end

function WindowClass:GetLanguage()
    return self.LanguageCode or self.DefaultLanguage or "en-US"
end
function WindowClass:SetLibraryLanguage(languageCode)
    if type(languageCode) ~= "string" or not (self.LibraryLocaleLabels and self.LibraryLocaleLabels[languageCode]) then
        return false
    end
    self.LibraryLanguageCode = languageCode
    self.State.set("libraryLanguage", languageCode)
    if self.LibraryLanguageDropdown and self.LibraryLanguageDropdown.SetSilent then
        self.LibraryLanguageDropdown:SetSilent(self.LibraryLocaleLabels[languageCode])
    end
    local developerCode = self.LanguageCode or self.DefaultLanguage
    local developer = self.Languages and self.Languages[developerCode]
    local merged = {}
    for key, value in pairs(developer and developer.Translations or {}) do merged[key] = value end
    local library = self.LibraryTranslations and self.LibraryTranslations[languageCode]
    if type(library) == "table" then
        for key, value in pairs(library) do merged[key] = value end
    end
    GGH.setLanguage(developerCode, {[developerCode] = {Translations = merged}})
    return true
end

function WindowClass:AddLanguage(languageOption)
    local mergedOptions = {}
    for _, language in pairs(self.LanguageOptionsRaw or {}) do
        mergedOptions[#mergedOptions + 1] = language
    end
    mergedOptions[#mergedOptions + 1] = languageOption
    self.LanguageOptionsRaw = mergedOptions
    self.Languages, self.LanguageLabels, self.LanguageCodeByLabel = normalizeLanguageList(mergedOptions)
    if self.LanguageCode and not self.Languages[self.LanguageCode] then
        self.LanguageCode = nil
    end
    if not self.LanguageCode then
        for code in pairs(self.Languages) do
            self.LanguageCode = code
            break
        end
    end
    GGH.setLanguage(self.LanguageCode, self.Languages)
    return self.LanguageCode
end

local function resolveExternalImage(url)
    if type(url) ~= "string" or not url:match("^https?://") then
        return url
    end
    if not (game.HttpGet and writefile and getcustomasset) then
        return url
    end
    local HttpService = game:GetService("HttpService")
    local hash = 2166136261
    for i = 1, #url do
        hash = bit32.bxor(hash, string.byte(url, i))
        hash = (hash * 16777619) % 4294967296
    end
    local pathPart = url:match("^https?://[^/]+([^?#]*)") or ""
    local ext = pathPart:match("%.([%w]+)$")
    if not ext then ext = "img" end
    ext = string.lower(ext)
    local folder, file = "GGH/images", string.format("GGH/images/%08x.%s", hash, ext)
    local ok, asset = pcall(function()
        if isfolder and makefolder and not isfolder("GGH") then makefolder("GGH") end
        if isfolder and makefolder and not isfolder(folder) then makefolder(folder) end
        if isfile and isfile(file) then return getcustomasset(file) end
        local data = game:HttpGet(url)
        if type(data) ~= "string" or #data == 0 then error("empty image response") end
        writefile(file, data)
        return getcustomasset(file)
    end)
    return ok and asset or url
end

function WindowClass:SetCustomBackground(imageReference, transparency)
    local bgLayers = self.BgLayers
    if not bgLayers or not bgLayers.pattern or not bgLayers.pattern.Parent then
        return false
    end
    local asset = normalizeImageAsset(imageReference)
    if asset then asset = resolveExternalImage(asset) end
    if not asset then
        if self.CustomBackgroundImage then
            self.CustomBackgroundImage.Visible = false
        end
        self.CustomBackground = nil
        self.State.set("customBackground", nil)
        self.State.set("customBackgroundTransparency", nil)
        return true
    end
    local parent = bgLayers.pattern.Parent
    local image = self.CustomBackgroundImage
    if not image or not image.Parent then
        image = Instance.new("ImageLabel")
        image.Name = "DeveloperCustomBackground"
        image.BackgroundTransparency = 1
        image.BorderSizePixel = 0
        image.Size = UDim2.fromScale(1, 1)
        image.Position = UDim2.fromScale(0, 0)
        image.ScaleType = Enum.ScaleType.Crop
        image.ZIndex = 0
        image.Parent = parent
        self.CustomBackgroundImage = image
    end
    local imageTransparency = math.clamp(tonumber(transparency) or self.CustomBackgroundTransparency or 0.45, 0, 1)
    local success = pcall(function()
        image.Image = asset
        image.ImageTransparency = imageTransparency
        image.Visible = true
    end)
    if not success then
        return false
    end
    self.CustomBackground = asset
    self.CustomBackgroundTransparency = imageTransparency
    self.State.set("customBackground", asset)
    self.State.set("customBackgroundTransparency", imageTransparency)
    return true
end

function WindowClass:SetCustomTheme(themeOptions)
    if type(themeOptions) ~= "table" then
        return false
    end
    local colorTokens, savedTokens = {}, {}
    for _, tokenName in ipairs(THEME_TOKEN_NAMES) do
        local color = parseThemeColor(themeOptions[tokenName])
        if color then
            colorTokens[tokenName] = color
            savedTokens[tokenName] = color:ToHex()
        end
    end
    if next(colorTokens) == nil then
        return false
    end
    Theme.setMany(colorTokens)
    Theme.base = "Custom"
    self.PanelColor = colorTokens.Background or self.PanelColor
    self.State.set("base", "Custom")
    self.State.set("customTheme", savedTokens)
    self.State.set("panel", colorTokens.Background and colorTokens.Background:ToHex() or nil)
    return true
end

function WindowClass:ClearCustomTheme()
    self.State.set("customTheme", nil)
    self.PanelColor = nil
    self.State.set("panel", nil)
    self.State.set("base", nil)
    return self:SetBase("Midnight")
end

local originalCreateWindowWithEnhancements = Library.CreateWindow
function Library.CreateWindow(selfOrOptions, maybeOptions)
    local options = maybeOptions
    if selfOrOptions ~= Library and type(selfOrOptions) == "table" and maybeOptions == nil then
        options = selfOrOptions
    end
    options = copy(options or {})
    local window = originalCreateWindowWithEnhancements(Library, options)
    window.LanguageOptionsRaw = options.Languages or options.AvailableLanguages
    window.AllowCustomBackground = options.AllowCustomBackground == true
    window.Languages, window.LanguageLabels, window.LanguageCodeByLabel = normalizeLanguageList(window.LanguageOptionsRaw)
    window.LanguageSelectionEnabled = options.EnableLanguageSelection == true or options.LanguageSelectionEnabled == true
    window.LibraryLanguageEnabled = options.EnableLibraryLanguageSelection ~= false
    window.LibraryLocaleOptions, window.LibraryLocaleLabels, window.LibraryLocaleCodeByLabel = libraryLocaleOptions()
    window.LibraryLanguageCode = window.State.get("libraryLanguage", "en")
    if not window.LibraryLocaleLabels[window.LibraryLanguageCode] then window.LibraryLanguageCode = "en" end
    window.LibraryTranslations = LIBRARY_TRANSLATIONS
    if type(options.LibraryTranslations) == "table" then
        for code, phrases in pairs(options.LibraryTranslations) do
            if type(phrases) == "table" then
                window.LibraryTranslations[code] = window.LibraryTranslations[code] or {}
                for phrase, translated in pairs(phrases) do
                    if type(phrase) == "string" and type(translated) == "string" then
                        window.LibraryTranslations[code][phrase] = translated
                    end
                end
            end
        end
    end
    window.DefaultLanguage = tostring(options.DefaultLanguage or options.Language or "")
    if window.DefaultLanguage == "" or not window.Languages[window.DefaultLanguage] then
        for code in pairs(window.Languages) do
            window.DefaultLanguage = code
            break
        end
    end
    if next(window.Languages) then
        local savedLanguage = window.State.get("language", nil)
        local initialLanguage = type(savedLanguage) == "string" and window.Languages[savedLanguage] and savedLanguage
            or window.DefaultLanguage
        window.LanguageCode = initialLanguage
        GGH.setLanguage(initialLanguage, window.Languages)
        window:SetLibraryLanguage(window.LibraryLanguageCode)
    end

    local developerTheme = options.CustomTheme or options.ThemeColors
    local savedTheme = window.State.get("customTheme", nil)
    if type(savedTheme) == "table" and next(savedTheme) then
        window:SetCustomTheme(savedTheme)
    elseif type(developerTheme) == "table" then
        window:SetCustomTheme(developerTheme)
    end
    local savedBackground = window.State.get("customBackground", nil)
    local defaultBackground = options.BackgroundImage or options.CustomBackground or options.BackgroundUrl
    local chosenBackground = type(savedBackground) == "string" and savedBackground ~= "" and savedBackground
        or defaultBackground
    local savedTransparency = tonumber(window.State.get("customBackgroundTransparency", nil))
    local defaultTransparency = tonumber(options.BackgroundImageTransparency or options.BackgroundTransparency)
    if chosenBackground then
        window:SetCustomBackground(chosenBackground, savedTransparency or defaultTransparency or 0.45)
    end
    return window
end

local originalOpenSettingsWithEnhancements = WindowClass._openSettingsTab
function WindowClass:_openSettingsTab(...)
    if self.SidebarCollapsed and self.SetSidebarCollapsed then
        pcall(function() self:SetSidebarCollapsed(false, true) end)
    end
    local result = originalOpenSettingsWithEnhancements(self, ...)
    if self.SettingsTab and not self._languageSectionCreated and self.LanguageSelectionEnabled then
        if self.Languages and next(self.Languages) then
            local section = self.SettingsTab:Section({
                Title = "Language",
                Icon = "languages",
            })
            local selectedLabel
            for label, code in pairs(self.LanguageCodeByLabel or {}) do
                if code == self.LanguageCode then
                    selectedLabel = label
                    break
                end
            end
            local languageDropdown = section:Dropdown({
                Text = "Interface language",
                Options = self.LanguageLabels,
                Default = selectedLabel,
                Callback = function(selectedLanguageLabel)
                    local selectedCode = self.LanguageCodeByLabel and self.LanguageCodeByLabel[selectedLanguageLabel]
                    if selectedCode then
                        self:SetLanguage(selectedCode)
                    end
                end,
            })
            self.LanguageDropdown = languageDropdown
            section:Paragraph({
                Text = "Your language choice is saved with this interface configuration.",
            })
        end
        self._languageSectionCreated = true
    end
    if self.SettingsTab and not self._libraryLanguageSectionCreated and self.LibraryLanguageEnabled then
        local section = self.SettingsTab:Section({ Title = "Library language", Icon = "languages" })
        local label = self.LibraryLocaleLabels and self.LibraryLocaleLabels[self.LibraryLanguageCode] or "English (en)"
        self.LibraryLanguageDropdown = section:Dropdown({
            Text = "Library text language", Options = self.LibraryLocaleOptions, Default = label,
            Callback = function(selected)
                local code = self.LibraryLocaleCodeByLabel and self.LibraryLocaleCodeByLabel[selected]
                if code then
                    self.LibraryLanguageCode = code
                    self.State.set("libraryLanguage", code)
                    self:SetLibraryLanguage(code)
                end
            end,
        })
        section:Paragraph({ Text = "Library translations are used when supplied; missing entries fall back to the developer’s original language (English by default)." })
        self._libraryLanguageSectionCreated = true
    end
    if self.SettingsTab and not self._customBackgroundSectionCreated and self.AllowCustomBackground then
        local section = self.SettingsTab:Section({
            Title = "Custom background",
            Icon = "image",
        })
        section:Input({
            Text = "Image URL or Roblox asset ID",
            Placeholder = "rbxassetid://123456789",
            Default = self.CustomBackground or "",
            Callback = function(value)
                self:SetCustomBackground(value)
            end,
        })
        section:Paragraph({
            Text = "Roblox asset IDs are the most reliable option; external links depend on platform permissions.",
        })
        self._customBackgroundSectionCreated = true
    end
    return result
end

local originalDestroyWithEnhancements = WindowClass.Destroy
function WindowClass:Destroy(...)
    if self.CustomBackgroundImage then
        pcall(function()
            self.CustomBackgroundImage:Destroy()
        end)
        self.CustomBackgroundImage = nil
    end
    return originalDestroyWithEnhancements(self, ...)
end


return Library
